import { useEffect } from 'react';
import { Fragment } from 'react/jsx-runtime';
import { useParams } from 'react-router-dom';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useSetHeaderRight } from '~/widgets/sub-layout/use-sub-layout';
import { useDeleteCmmntyManageMutation } from '~/entities/community/api/use-delete-cmmnty-manage-mutation';
import { useGetCmmntyManageQuery } from '~/entities/community/api/use-get-cmmnty-manage-query';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { overlay } from '~/shared/lib/overlay';
import { parseToDate } from '~/shared/lib/web-view-bridge';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const InquiryDetailPage = () => {
  const { nttManageId } = useParams();
  const { navigate, navigateBack } = useNavigate();
  const { data, isLoading } = useGetCmmntyManageQuery(nttManageId ?? '');
  const { mutateAsync: deleteCmmntyManage } = useDeleteCmmntyManageMutation();

  const fnGoModify = () => {
    navigate(`${PATHS.community.inquiryModify}${nttManageId}`, { state: nttManageId });
  };
  const fnRemoveDetail = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={
            <div className="whitespace-pre-line break-words">{i18n.t('validation:deleteInquiryConfirmation')}</div>
          }
          buttonLabel={[i18n.t('cancel'), i18n.t('delete')]}
          onConfirmClick={() => {
            deleteCmmntyManage(data!.tbCmmntyMastr!).then(() => {
              navigateBack();
            });
          }}
        />
      );
    });
  };

  useSetHeaderRight(
    <Fragment>
      {!data?.tbCmmntyMastr?.answerCn && (
        <button
          type="button"
          className="btn top-more-btn"
          onClick={() => {
            document.querySelector('.more-menu')?.classList.add('on');
          }}
          data-testid="more-button"
        >
          <span>더보기 버튼</span>
        </button>
      )}
    </Fragment>,
  );
  const fnHide = (event: any) => {
    if (
      event?.target?.className !== 'more' &&
      event?.target?.className !== 'more-menu' &&
      event?.target?.className !== 'more-menu-btn' &&
      event?.target?.className !== 'btn top-more-btn'
    ) {
      document.querySelector('.more-menu')?.classList.remove('on');
    }
  };
  useEffect(() => {
    document.onmousedown = fnHide;
  }, []);
  return (
    <div className="content sub has-btm-btn">
      {isLoading && <FullScreenLoading />}
      {!data?.tbCmmntyMastr?.answerCn && (
        <div className="more-menu">
          <ul className="more">
            <li className="more">
              <button type="button" className="more-menu-btn" onClick={fnGoModify}>
                <span className="more">{i18n.t('edit')}</span>
              </button>
            </li>
            <li>
              <button type="button" className="more-menu-btn" onClick={fnRemoveDetail}>
                <span className="more">{i18n.t('delete')}</span>
              </button>
            </li>
          </ul>
        </div>
      )}
      <div className="board-view">
        <div className="border-view-top">
          <div className="qna-label">
            {data?.tbCmmntyMastr?.ctgryNm && <span className="qna-tag">{data?.tbCmmntyMastr?.ctgryNm}</span>}{' '}
            <span className={`qna-sttus ${data?.tbCmmntyMastr?.answerCn ? 'on' : ''}`}>
              {data?.tbCmmntyMastr?.answerCn ? i18n.t('answerCompleted') : i18n.t('inProgress')}
            </span>
          </div>
          <h3>{data?.tbCmmntyMastr?.nttSj}</h3>
          <span>{parseToDate(data?.tbCmmntyMastr?.registDt, 'yyyy.MM.dd')}</span>
        </div>
        <div className="border-view-content">
          <p className="whitespace-pre-line break-words">{data?.tbCmmntyMastr?.nttCn ?? ''}</p>
        </div>
        <div className="qna-answer" hidden={data?.tbCmmntyMastr?.answerCn ? false : true}>
          <p className="whitespace-pre-line break-words">{data?.tbCmmntyMastr?.answerCn ?? ''}</p>
          <span>{parseToDate(data?.tbCmmntyMastr?.answerDt, 'yyyy.MM.dd')}</span>
        </div>
      </div>
    </div>
  );
};
